-- Mr Ghosh: new company story (About page), firmer SOPAN profile without cylinder testing, tidy labels.
UPDATE "site_settings" SET "data" = jsonb_set("data", '{company,about}', to_jsonb('Chanrai Nigeria Limited is the equipment business of the Kewalram Chanrai Group in Nigeria. We bring three lines of proven equipment to the businesses that keep the country moving: CNG refueling, compression, storage and dispensing equipment from SOPAN and Fornovo Gas, LiuGong construction equipment, and BYD electric forklifts.

We are one partner for the whole life of the equipment. We help you choose the right machine for the job, supply and install it, and keep it working with field service, service agreements and genuine parts. Our desk is open 24 hours a day, 7 days a week, for every product we supply.

Our customers are CNG station operators, gas distributors, contractors, fleet operators, warehouses and manufacturers across Nigeria.'::text)) WHERE "data"->'company'->>'about' LIKE 'Chanrai Nigeria supplies %';--> statement-breakpoint
UPDATE "site_settings" SET "data" = jsonb_set("data", '{company,heritage}', to_jsonb('Behind us stands the Kewalram Chanrai Group, in Nigeria since 1900: more than 125 years of doing business in the country.'::text)) WHERE "data"->'company'->>'heritage' = 'The Kewalram Chanrai Group has been in Nigeria since 1900.';--> statement-breakpoint
UPDATE "brands" SET "about" = 'SOPAN is an Indian energy-services group with offices in Pune, Ahmedabad and Delhi and a Gulf entity, Sopan Energy Contracting LLC. Its equipment business, Sopan Process Technologies (SPTL), designs and builds CNG and compressed-biogas station equipment: hydraulic booster and online reciprocating compressors, dispensers, and metering, pressure-regulating and decompression skids. The group also delivers EPC projects and the operation and maintenance of compression systems and gas networks, backed by more than 20 years in oil and gas, city gas distribution and biogas.' WHERE "slug" = 'sopan' AND "about" LIKE 'SOPAN is an Indian energy-services group%';--> statement-breakpoint
UPDATE "page_content" SET "data" = replace("data"::text, 'Equipment lines: CNG and gas, construction, forklifts', 'Equipment lines: CNG, construction and forklifts')::jsonb WHERE "data"::text LIKE '%CNG and gas, construction%';--> statement-breakpoint
UPDATE "posts" SET "category" = 'CNG' WHERE "category" = 'CNG and gas';
